LESSONS.push(...[{"id":"py-gearex-1","lang":"py","title":"Hello, Python","level":"Beginner","description":"Python executes readable statements without a separate compilation step.","intro":"Python executes readable statements without a separate compilation step. The example below demonstrates hello, python in Python.","code":"print('Hello, GearEx!')","syntax":"print(value) displays a value; strings can use single or double quotes.","points":["print(value) displays a value; strings can use single or double quotes.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Hello, GearEx!","walkthrough":"Study the syntax: print(value) displays a value; strings can use single or double quotes. Follow the statements in order and compare the result with the output panel.","pitfalls":"Pay attention to case, spelling, and language-specific punctuation.","challenge":"Change the greeting and run it."},{"id":"py-gearex-2","lang":"py","title":"Variables and types","level":"Beginner","description":"Names reference values; Python infers types when you assign.","intro":"Names reference values; Python infers types when you assign. The example below demonstrates variables and types in Python.","code":"name = 'Ada'\nscore = 95\nprint(f'{name}: {score}')","syntax":"name = value creates a binding; f-strings interpolate expressions.","points":["name = value creates a binding; f-strings interpolate expressions.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Ada: 95","walkthrough":"Study the syntax: name = value creates a binding; f-strings interpolate expressions. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Store a second score and print it."},{"id":"py-gearex-3","lang":"py","title":"If and else","level":"Beginner","description":"Branch based on a Boolean condition; indentation defines each block.","intro":"Branch based on a Boolean condition; indentation defines each block. The example below demonstrates if and else in Python.","code":"score = 76\nif score >= 50:\n    print('Pass')\nelse:\n    print('Retry')","syntax":"if condition: begins a branch; else: handles the remaining case.","points":["if condition: begins a branch; else: handles the remaining case.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Pass","walkthrough":"Study the syntax: if condition: begins a branch; else: handles the remaining case. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Change score below 50 and explain the result."},{"id":"py-gearex-4","lang":"py","title":"For loops and range","level":"Intermediate","description":"Repeat a task for a known sequence of values.","intro":"Repeat a task for a known sequence of values. The example below demonstrates for loops and range in Python.","code":"for i in range(1, 4):\n    print(i)","syntax":"range(1,4) produces 1, 2, 3; the endpoint is excluded.","points":["range(1,4) produces 1, 2, 3; the endpoint is excluded.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"1\n2\n3","walkthrough":"Study the syntax: range(1,4) produces 1, 2, 3; the endpoint is excluded. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Change the loop to print five values."},{"id":"py-gearex-5","lang":"py","title":"Functions","level":"Intermediate","description":"Package reusable operations with parameters and return values.","intro":"Package reusable operations with parameters and return values. The example below demonstrates functions in Python.","code":"def add(a, b):\n    return a + b\n\nprint(add(3, 5))","syntax":"def name(parameters): defines a function; return gives back its result.","points":["def name(parameters): defines a function; return gives back its result.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"8","walkthrough":"Study the syntax: def name(parameters): defines a function; return gives back its result. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Write a function that multiplies two numbers."},{"id":"py-gearex-6","lang":"py","title":"Lists","level":"Intermediate","description":"Lists store ordered, changeable collections.","intro":"Lists store ordered, changeable collections. The example below demonstrates lists in Python.","code":"numbers = [3, 5, 8]\nnumbers.append(13)\nprint(numbers[1])","syntax":"list[index] reads a zero-based position; append adds an item.","points":["list[index] reads a zero-based position; append adds an item.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"5","walkthrough":"Study the syntax: list[index] reads a zero-based position; append adds an item. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Add a number and print the final list."},{"id":"py-gearex-7","lang":"py","title":"Dictionaries","level":"Advanced","description":"Dictionaries map unique keys to values.","intro":"Dictionaries map unique keys to values. The example below demonstrates dictionaries in Python.","code":"learner = {'name': 'Ada', 'score': 95}\nprint(learner['name'])","syntax":"dict[key] fetches a value; keys must be hashable.","points":["dict[key] fetches a value; keys must be hashable.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Ada","walkthrough":"Study the syntax: dict[key] fetches a value; keys must be hashable. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Add a course key and retrieve it."},{"id":"py-gearex-8","lang":"py","title":"Classes and objects","level":"Advanced","description":"Classes group related data and behavior.","intro":"Classes group related data and behavior. The example below demonstrates classes and objects in Python.","code":"class Learner:\n    def __init__(self, name):\n        self.name = name\n    def greet(self):\n        return 'Hi, ' + self.name\n\nprint(Learner('Ada').greet())","syntax":"class defines a type; self accesses the current instance.","points":["class defines a type; self accesses the current instance.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Hi, Ada","walkthrough":"Study the syntax: class defines a type; self accesses the current instance. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Add a score field to the class."}]);
