LESSONS.push(...[{"id":"cs-gearex-1","lang":"cs","title":"Hello, C#","level":"Beginner","description":"C# programs can run on .NET and organize behavior into classes.","intro":"C# programs can run on .NET and organize behavior into classes. The example below demonstrates hello, c# in C#.","code":"using System;\nclass Program {\n  static void Main() {\n    Console.WriteLine(\"Hello, GearEx!\");\n  }\n}","syntax":"using System imports common types; Console.WriteLine prints text.","points":["using System imports common types; Console.WriteLine prints text.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Hello, GearEx!","walkthrough":"Study the syntax: using System imports common types; Console.WriteLine prints text. Follow the statements in order and compare the result with the output panel.","pitfalls":"Pay attention to case, spelling, and language-specific punctuation.","challenge":"Change the greeting."},{"id":"cs-gearex-2","lang":"cs","title":"Variables and types","level":"Beginner","description":"C# is statically typed and also supports type inference with var.","intro":"C# is statically typed and also supports type inference with var. The example below demonstrates variables and types in C#.","code":"using System;\nclass Program {\n  static void Main() {\n    string name = \"Ada\";\n    int score = 95;\n    Console.WriteLine($\"{name}: {score}\");\n  }\n}","syntax":"string stores text; $\"...\" interpolates variables.","points":["string stores text; $\"...\" interpolates variables.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Ada: 95","walkthrough":"Study the syntax: string stores text; $\"...\" interpolates variables. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Store a decimal value."},{"id":"cs-gearex-3","lang":"cs","title":"If and else","level":"Beginner","description":"Conditionals choose the appropriate block.","intro":"Conditionals choose the appropriate block. The example below demonstrates if and else in C#.","code":"using System;\nclass Program {\n  static void Main() {\n    int score = 76;\n    if (score >= 50) Console.WriteLine(\"Pass\");\n    else Console.WriteLine(\"Retry\");\n  }\n}","syntax":"if (condition) branches; == tests equality.","points":["if (condition) branches; == tests equality.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Pass","walkthrough":"Study the syntax: if (condition) branches; == tests equality. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Try a lower score."},{"id":"cs-gearex-4","lang":"cs","title":"For loops","level":"Intermediate","description":"A for loop is suitable for counting repetitions.","intro":"A for loop is suitable for counting repetitions. The example below demonstrates for loops in C#.","code":"using System;\nclass Program {\n  static void Main() {\n    for (int i = 1; i <= 3; i++) Console.WriteLine(i);\n  }\n}","syntax":"for (initialization; test; update) controls iteration.","points":["for (initialization; test; update) controls iteration.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"1\n2\n3","walkthrough":"Study the syntax: for (initialization; test; update) controls iteration. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Print multiples of three."},{"id":"cs-gearex-5","lang":"cs","title":"Methods","level":"Intermediate","description":"A method can accept arguments and return a typed result.","intro":"A method can accept arguments and return a typed result. The example below demonstrates methods in C#.","code":"using System;\nclass Program {\n  static int Add(int a, int b) { return a + b; }\n  static void Main() { Console.WriteLine(Add(3, 5)); }\n}","syntax":"static int Add(...) declares a method; return supplies its result.","points":["static int Add(...) declares a method; return supplies its result.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"8","walkthrough":"Study the syntax: static int Add(...) declares a method; return supplies its result. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Add a subtraction method."},{"id":"cs-gearex-6","lang":"cs","title":"Arrays","level":"Intermediate","description":"Arrays are typed, fixed-length indexed collections.","intro":"Arrays are typed, fixed-length indexed collections. The example below demonstrates arrays in C#.","code":"using System;\nclass Program {\n  static void Main() {\n    int[] numbers = {3, 5, 8};\n    Console.WriteLine(numbers[1]);\n  }\n}","syntax":"int[] defines a numeric array; indexes start at zero.","points":["int[] defines a numeric array; indexes start at zero.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"5","walkthrough":"Study the syntax: int[] defines a numeric array; indexes start at zero. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Print the array length."},{"id":"cs-gearex-7","lang":"cs","title":"Classes and properties","level":"Advanced","description":"Properties expose managed access to an object's data.","intro":"Properties expose managed access to an object's data. The example below demonstrates classes and properties in C#.","code":"using System;\nclass Learner { public string Name { get; set; } = \"Ada\"; }\nclass Program {\n  static void Main() { Console.WriteLine(new Learner().Name); }\n}","syntax":"get and set accessors define a property; new constructs an object.","points":["get and set accessors define a property; new constructs an object.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Ada","walkthrough":"Study the syntax: get and set accessors define a property; new constructs an object. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Add a Score property."},{"id":"cs-gearex-8","lang":"cs","title":"LINQ fundamentals","level":"Advanced","description":"LINQ operators can filter and transform collections.","intro":"LINQ operators can filter and transform collections. The example below demonstrates linq fundamentals in C#.","code":"using System;\nusing System.Linq;\nclass Program {\n  static void Main() {\n    int[] scores = {2, 5, 8};\n    Console.WriteLine(string.Join(\",\", scores.Where(x => x > 3)));\n  }\n}","syntax":"Where(predicate) filters values; lambda x => condition expresses a function.","points":["Where(predicate) filters values; lambda x => condition expresses a function.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"5,8","walkthrough":"Study the syntax: Where(predicate) filters values; lambda x => condition expresses a function. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Change the predicate to filter even numbers."}]);
QUESTIONS.push(...[{"id":"cs-gearex-q1","lang":"cs","question":"Which method prints text in C#?","options":["System.out.println","Console.WriteLine","console.log","print"],"answer":1,"explanation":"In C#, the correct answer is Console.WriteLine. See lesson Hello, C# and its syntax notes for context."},{"id":"cs-gearex-q2","lang":"cs","question":"Which syntax interpolates a string?","options":["@\"...\"","$\"...\"","%\"...\"","&\"...\""],"answer":1,"explanation":"In C#, the correct answer is $\"...\". See lesson Variables and types and its syntax notes for context."},{"id":"cs-gearex-q3","lang":"cs","question":"Which keyword creates an object?","options":["new","make","build","create"],"answer":0,"explanation":"In C#, the correct answer is new. See lesson If and else and its syntax notes for context."},{"id":"cs-gearex-q4","lang":"cs","question":"What is the first array index?","options":["1","2","0","-1"],"answer":2,"explanation":"In C#, the correct answer is 0. See lesson For loops and its syntax notes for context."},{"id":"cs-gearex-q5","lang":"cs","question":"Which namespace supports common LINQ methods?","options":["System.IO","System.Text","System.Linq","System.Math"],"answer":2,"explanation":"In C#, the correct answer is System.Linq. See lesson Methods and its syntax notes for context."},{"id":"cs-gearex-q6","lang":"cs","question":"What do get and set define?","options":["Loop","Property accessors","Constructor","Interface"],"answer":1,"explanation":"In C#, the correct answer is Property accessors. See lesson Arrays and its syntax notes for context."},{"id":"cs-gearex-q7","lang":"cs","question":"Which type represents text?","options":["StringBuilder only","char only","string","text"],"answer":2,"explanation":"In C#, the correct answer is string. See lesson Classes and properties and its syntax notes for context."},{"id":"cs-gearex-q8","lang":"cs","question":"What does Where(...) do in LINQ?","options":["Sort","Filter","Count always","Delete"],"answer":1,"explanation":"In C#, the correct answer is Filter. See lesson LINQ fundamentals and its syntax notes for context."}]);
