LESSONS.push(...[{"id":"sql-gearex-1","lang":"sql","title":"Select rows","level":"Beginner","description":"SQL retrieves data from tables through SELECT.","intro":"SQL retrieves data from tables through SELECT. The example below demonstrates select rows in SQL.","code":"WITH learners(name, score) AS (VALUES ('Ada',95),('Sam',72))\nSELECT name FROM learners;","syntax":"SELECT columns FROM table selects fields; each result is a row.","points":["SELECT columns FROM table selects fields; each result is a row.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Ada\nSam","walkthrough":"Study the syntax: SELECT columns FROM table selects fields; each result is a row. Follow the statements in order and compare the result with the output panel.","pitfalls":"Pay attention to case, spelling, and language-specific punctuation.","challenge":"Select the score column too."},{"id":"sql-gearex-2","lang":"sql","title":"Filter with WHERE","level":"Beginner","description":"WHERE limits rows based on a predicate.","intro":"WHERE limits rows based on a predicate. The example below demonstrates filter with where in SQL.","code":"WITH learners(name, score) AS (VALUES ('Ada',95),('Sam',72))\nSELECT name FROM learners WHERE score >= 80;","syntax":"WHERE score >= 80 filters rows before projection.","points":["WHERE score >= 80 filters rows before projection.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Ada","walkthrough":"Study the syntax: WHERE score >= 80 filters rows before projection. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Filter for scores below 80."},{"id":"sql-gearex-3","lang":"sql","title":"Sort results","level":"Beginner","description":"ORDER BY sorts result rows ascending or descending.","intro":"ORDER BY sorts result rows ascending or descending. The example below demonstrates sort results in SQL.","code":"WITH learners(name, score) AS (VALUES ('Ada',95),('Sam',72))\nSELECT name FROM learners ORDER BY score DESC;","syntax":"ORDER BY score DESC sorts highest first; ASC sorts lowest first.","points":["ORDER BY score DESC sorts highest first; ASC sorts lowest first.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Ada\nSam","walkthrough":"Study the syntax: ORDER BY score DESC sorts highest first; ASC sorts lowest first. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Try ascending order."},{"id":"sql-gearex-4","lang":"sql","title":"Aggregate values","level":"Intermediate","description":"COUNT, SUM, AVG and other aggregates summarize rows.","intro":"COUNT, SUM, AVG and other aggregates summarize rows. The example below demonstrates aggregate values in SQL.","code":"WITH scores(score) AS (VALUES (10),(20),(30))\nSELECT SUM(score) FROM scores;","syntax":"SUM(column) adds values; AVG(column) computes an average.","points":["SUM(column) adds values; AVG(column) computes an average.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"60","walkthrough":"Study the syntax: SUM(column) adds values; AVG(column) computes an average. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Compute the average instead."},{"id":"sql-gearex-5","lang":"sql","title":"Group and count","level":"Intermediate","description":"GROUP BY collects rows sharing a key.","intro":"GROUP BY collects rows sharing a key. The example below demonstrates group and count in SQL.","code":"WITH learners(lang) AS (VALUES ('C'),('C'),('Python'))\nSELECT lang, COUNT(*) FROM learners GROUP BY lang;","syntax":"GROUP BY lang creates groups; COUNT(*) counts rows in each.","points":["GROUP BY lang creates groups; COUNT(*) counts rows in each.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"C|2\nPython|1","walkthrough":"Study the syntax: GROUP BY lang creates groups; COUNT(*) counts rows in each. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Group different sample data."},{"id":"sql-gearex-6","lang":"sql","title":"Join related tables","level":"Intermediate","description":"JOIN combines related tables using matching keys.","intro":"JOIN combines related tables using matching keys. The example below demonstrates join related tables in SQL.","code":"WITH students(id, name) AS (VALUES (1,'Ada'),(2,'Sam')),\nmarks(id, score) AS (VALUES (1,95),(2,72))\nSELECT students.name, marks.score FROM students\nJOIN marks ON students.id = marks.id;","syntax":"JOIN ... ON ... links tables by related columns.","points":["JOIN ... ON ... links tables by related columns.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Ada|95\nSam|72","walkthrough":"Study the syntax: JOIN ... ON ... links tables by related columns. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Try INNER JOIN explicitly."},{"id":"sql-gearex-7","lang":"sql","title":"Create and insert","level":"Advanced","description":"Define a table, then add records.","intro":"Define a table, then add records. The example below demonstrates create and insert in SQL.","code":"CREATE TABLE learners (id INTEGER, name TEXT);\nINSERT INTO learners VALUES (1, 'Ada');\nSELECT name FROM learners;","syntax":"CREATE TABLE declares structure; INSERT INTO adds a row.","points":["CREATE TABLE declares structure; INSERT INTO adds a row.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"Ada","walkthrough":"Study the syntax: CREATE TABLE declares structure; INSERT INTO adds a row. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Insert a second learner."},{"id":"sql-gearex-8","lang":"sql","title":"Update and delete","level":"Advanced","description":"UPDATE changes matching rows; DELETE removes matching rows.","intro":"UPDATE changes matching rows; DELETE removes matching rows. The example below demonstrates update and delete in SQL.","code":"CREATE TABLE learners (id INTEGER, score INTEGER);\nINSERT INTO learners VALUES (1, 50);\nUPDATE learners SET score = 95 WHERE id = 1;\nSELECT score FROM learners;","syntax":"Always consider WHERE when updating or deleting rows.","points":["Always consider WHERE when updating or deleting rows.","Trace the values and output before running the sample.","Make one small change and compare the result."],"output":"95","walkthrough":"Study the syntax: Always consider WHERE when updating or deleting rows. Follow the statements in order and compare the result with the output panel.","pitfalls":"Do not assume all languages share the same syntax or type rules.","challenge":"Try updating another record."}]);
QUESTIONS.push(...[{"id":"sql-gearex-q1","lang":"sql","question":"Which statement retrieves rows?","options":["SELECT","INSERT","UPDATE","CREATE"],"answer":0,"explanation":"In SQL, the correct answer is SELECT. See lesson Select rows and its syntax notes for context."},{"id":"sql-gearex-q2","lang":"sql","question":"Which clause filters rows?","options":["ORDER BY","GROUP BY","WHERE","JOIN"],"answer":2,"explanation":"In SQL, the correct answer is WHERE. See lesson Filter with WHERE and its syntax notes for context."},{"id":"sql-gearex-q3","lang":"sql","question":"What sorts from highest to lowest?","options":["ASC","DESC","COUNT","DISTINCT"],"answer":1,"explanation":"In SQL, the correct answer is DESC. See lesson Sort results and its syntax notes for context."},{"id":"sql-gearex-q4","lang":"sql","question":"Which aggregate counts rows?","options":["COUNT(*)","SUM(*)","LEN(*)","ROWS(*)"],"answer":0,"explanation":"In SQL, the correct answer is COUNT(*). See lesson Aggregate values and its syntax notes for context."},{"id":"sql-gearex-q5","lang":"sql","question":"Which clause groups shared values?","options":["ORDER BY","GROUP BY","WHERE","INSERT"],"answer":1,"explanation":"In SQL, the correct answer is GROUP BY. See lesson Group and count and its syntax notes for context."},{"id":"sql-gearex-q6","lang":"sql","question":"Which clause defines a join condition?","options":["AS","IN","ON","FROM ONLY"],"answer":2,"explanation":"In SQL, the correct answer is ON. See lesson Join related tables and its syntax notes for context."},{"id":"sql-gearex-q7","lang":"sql","question":"Which statement adds a new row?","options":["INSERT","UPDATE","ALTER","SELECT"],"answer":0,"explanation":"In SQL, the correct answer is INSERT. See lesson Create and insert and its syntax notes for context."},{"id":"sql-gearex-q8","lang":"sql","question":"Why is WHERE important in UPDATE?","options":["It adds columns","It limits changed rows","It sorts results","It deletes tables"],"answer":1,"explanation":"In SQL, the correct answer is It limits changed rows. See lesson Update and delete and its syntax notes for context."}]);
